// ===== CONFIGURACION DEL FLUJO (editar solo esta parte) =====
const FLUJO = "Autorrecuperacion BD MariaDB - T-200";
// Un objetivo por equipo/servicio. host = texto (regex) que debe aparecer en el nombre del host de Zabbix.
// {P} dentro de un comando se reemplaza por el parametro extraido del trigger (interfaz, VM, etc.).
const OBJETIVOS = {
  "db_ubuntu": {
    "host": "mariadb.*(ubuntu|linux)",
    "so": "linux",
    "etiqueta": "MariaDB Ubuntu (VM-03)",
    "diag": "echo \"load1=$(cut -d' ' -f1 /proc/loadavg)\"; echo \"cores=$(nproc)\"; echo \"mem_disp_pct=$(awk '/MemTotal/{t=$2}/MemAvailable/{a=$2}END{printf \"%d\",a*100/t}' /proc/meminfo)\"; echo \"disco_pct=$(df -P / | awk 'NR==2{gsub(\"%\",\"\",$5);print $5}')\"; echo \"top=$(ps -eo comm --sort=-%cpu | sed -n '2,4p' | tr '\\n' ',')\"",
    "reinicio": "sudo /usr/bin/systemctl restart mariadb",
    "verif": "systemctl is-active --quiet mariadb && ss -ltn | grep -q ':3306 ' && echo active || echo inactive",
    "esperado": "active"
  },
  "db_windows": {
    "host": "mariadb.*windows",
    "so": "windows",
    "etiqueta": "MariaDB Windows (VM-04)",
    "diag": "$c=(Get-CimInstance Win32_Processor | Measure-Object -Property LoadPercentage -Average).Average; $o=Get-CimInstance Win32_OperatingSystem; $m=[int](100*$o.FreePhysicalMemory/$o.TotalVisibleMemorySize); $d=Get-PSDrive C; $dp=[int](100*$d.Used/($d.Used+$d.Free)); \"cpu_pct=$c\"; \"mem_disp_pct=$m\"; \"disco_pct=$dp\"; $t=(Get-Process | Sort-Object CPU -Descending | Select-Object -First 3 | ForEach-Object { $_.ProcessName }) -join ','; \"top=$t\"",
    "reinicio": "Restart-Service -Name MariaDB -Force",
    "verif": "if ((Get-Service -Name MariaDB).Status -eq 'Running' -and (Test-NetConnection -ComputerName localhost -Port 3306 -WarningAction SilentlyContinue).TcpTestSucceeded) { 'Running' } else { 'NoActivo' }",
    "esperado": "Running"
  }
};
// Reglas: que triggers atiende este flujo y que hace con cada uno.
// tipo: "servicio_caido" = reiniciar siempre | "lento" = reiniciar si el diagnostico se pudo ejecutar | "diagnostico" = solo avisar con diagnostico
// solo_diagnostico (en un objetivo): ese equipo nunca se reinicia ni se modifica, solo se diagnostica.
// param: regex con un grupo que extrae del trigger (nombre de interfaz, VM...). permitidos: lista de valores permitidos (seguridad).
const REGLAS = [
  {
    "categoria": "QUERIES SQL LENTOS",
    "trigger": "slow quer|consultas? lent|quer(y|ies)|latencia.{0,20}sql|sql.{0,20}(latenc|lent|slow)",
    "tipo": "lento",
    "max": 2,
    "ventana_min": 30,
    "espera_s": 30
  },
  {
    "categoria": "CAIDA DE MARIADB",
    "trigger": "(mariadb|mysql|3306|base de datos).*(no disponible|not available|unavailable|\\bdown\\b|not running|ca[ií]d|service is down)|db_down",
    "tipo": "servicio_caido",
    "max": 2,
    "ventana_min": 15,
    "espera_s": 30
  }
];
const TZ_ZABBIX = '-06:00';   // Costa Rica, sin horario de verano
// ============================================================

const raw0 = $json.body !== undefined ? $json.body : $json;
let raw = raw0;
if (typeof raw0 === 'string') { try { raw = JSON.parse(raw0); } catch (_) { raw = { message: raw0 }; } }
if (!raw || typeof raw !== 'object') raw = { message: String(raw ?? '') };
if (typeof raw.message === 'string' && raw.message.trim().startsWith('{')) {
  try { const inner = JSON.parse(raw.message); if (inner && typeof inner === 'object') raw = { ...raw, ...inner, message: inner.message || '' }; } catch (_) {}
}
const limpiar = s => String(s || '').replace(/\{[A-Z_.]+\}/g, '').replace(/\s+/g, ' ').trim();
const get = (...keys) => { for (const k of keys) if (raw[k] !== undefined && raw[k] !== null && limpiar(raw[k]) !== '') return limpiar(raw[k]); return ''; };
const host = get('host', 'hostname', 'host_name');
const trigger = get('trigger', 'trigger_name', 'event_name');
const subject = get('subject', 'Subject', 'title');
const eventTime = get('event_time');
const st = get('status', 'event_status', 'event_value', 'value').toLowerCase();
const recuperado = ['ok', 'recovered', 'recovery', 'resolved', 'resuelto', 'recuperado', 'recuperada', '0'].includes(st)
  || /^(recovery|recovered|recuperad[oa]|resolved|resuelto|ok)\b/i.test(subject);

// ---------- regla y objetivo ----------
const T = trigger + ' ' + subject;
const regla = REGLAS.find(r => new RegExp(r.trigger, 'i').test(T)) || null;
let targetKey = null;
for (const k of Object.keys(OBJETIVOS)) if (new RegExp(OBJETIVOS[k].host, 'i').test(host)) { targetKey = k; break; }
const obj = targetKey ? OBJETIVOS[targetKey] : null;

// ---------- parametro (interfaz, VM...) ----------
let param = '', paramOk = true;
if (regla && regla.param) {
  const m = T.match(new RegExp(regla.param, 'i'));
  param = m ? String(m[1] || '').trim() : '';
  if (regla.mapa && param) { const k = Object.keys(regla.mapa).find(x => x.toLowerCase() === param.toLowerCase()); param = k ? String(regla.mapa[k]) : ''; }
  else if (regla.permitidos && param) { const k = regla.permitidos.find(x => x.toLowerCase() === param.toLowerCase()); param = k || ''; }
  paramOk = /^[A-Za-z0-9_.\/-]+$/.test(param);
}
const subst = c => String(c || '').replace(/\{P\}/g, param);

const autorizado = !!(regla && obj && !recuperado && paramOk);
let motivo = '';
if (recuperado) motivo = 'Aviso de recuperacion de Zabbix';
else if (!regla) motivo = 'El trigger no es de los que atiende este flujo';
else if (!obj) motivo = 'Host sin objetivo configurado en este flujo';
else if (!paramOk) motivo = 'Parametro no permitido o no encontrado en el trigger (' + (regla.param ? 'verificar lista permitidos' : '') + ')';

let tEventoMs = null;
if (eventTime) { const d = new Date(eventTime.replace(/\./g, '-').replace(' ', 'T') + TZ_ZABBIX); if (!isNaN(d)) tEventoMs = d.getTime(); }
const o = obj || {};
const diagCmd = subst((regla && regla.diag_obj && regla.diag_obj[targetKey]) || (regla && regla.diag) || o.diag);
return { json: {
  autorizado, es_recuperacion: recuperado, motivo,
  flujo: FLUJO, categoria: regla ? regla.categoria : '', tipo: (obj && obj.solo_diagnostico) ? 'diagnostico' : (regla ? regla.tipo : ''),
  target: targetKey || '', so: o.so || '', etiqueta: (o.etiqueta || host || 'desconocido') + (param && regla && regla.param ? ' [' + param + ']' : ''),
  param, diag_cmd: diagCmd,
  reinicio_cmd: subst((regla && regla.reinicio) || o.reinicio),
  verif_cmd: subst((regla && regla.verif) || o.verif),
  esperado: (regla && regla.esperado) || o.esperado || '',
  max: (regla && regla.max) || 2, ventana_min: (regla && regla.ventana_min) || 15, espera_s: (regla && regla.espera_s) || 30,
  host, trigger, event_time: eventTime || '', t_evento_ms: tEventoMs, t_inicio_ms: Date.now()
} };

// Analiza la salida del diagnostico y decide si se ejecuta la recuperacion.
const v = $('Validar objetivo e incidente').first().json;
const ssh = $json;
const out = String(ssh.stdout || '').trim();
const kv = {};
out.split(/\r?\n/).forEach(l => { const m = l.match(/^(\w+)=(.*)$/); if (m) kv[m[1]] = m[2].trim(); });
const sinDiag = !!ssh.error || out === '';
let diag;
if (v.so === 'linux' || v.so === 'windows') {
  const n = k => (kv[k] !== undefined && kv[k] !== '' && !isNaN(Number(kv[k]))) ? Number(kv[k]) : null;
  const cpu = v.so === 'linux' ? (n('load1') !== null ? 'load1=' + n('load1') + ' (' + (n('cores') || 1) + ' nucleos)' : 'n/d') : (n('cpu_pct') !== null ? n('cpu_pct') + ' %' : 'n/d');
  diag = ['CPU: ' + cpu, 'RAM disponible: ' + (n('mem_disp_pct') !== null ? n('mem_disp_pct') + ' %' : 'n/d'), 'Disco: ' + (n('disco_pct') !== null ? n('disco_pct') + ' % usado' : 'n/d'), kv.top ? 'Procesos top: ' + kv.top.replace(/,+$/, '') : null].filter(Boolean).join(' | ');
} else {
  diag = out.replace(/\s+/g, ' ').slice(0, 250) || 'sin salida';
}
let reiniciar = false, razon = '';
if (v.tipo === 'servicio_caido') { reiniciar = true; razon = 'Servicio caido segun Zabbix' + (sinDiag ? ' (el diagnostico no respondio)' : ''); }
else if (v.tipo === 'lento') { reiniciar = !sinDiag; razon = sinDiag ? 'No se pudo ejecutar el diagnostico' + (ssh.error ? ': ' + String(ssh.error.message || ssh.error).slice(0, 120) : '') : 'Alerta sostenida de Zabbix (' + v.categoria + ')'; }
else { reiniciar = false; razon = sinDiag ? 'No se pudo ejecutar el diagnostico' : 'Esta alerta solo se diagnostica (sin recuperacion automatica)'; }
return { json: { ...v, diag, reiniciar, razon, diag_ok: !sinDiag } };

const j = $json;

// Primer paso por aquí = intento 1.
// Si vuelve por el bucle, suma 1.
const intentoAnterior = Number(j.intento ?? 0);
const intentoActual = intentoAnterior + 1;

// Máximo configurado. Si no viene, usa 4.
const maxIntentos = Number(j.max ?? j.max_reinicios ?? 4);

return {
  json: {
    ...j,
    intento: intentoActual,
    intentos_en_ventana: intentoActual,
    max: maxIntentos,
    max_reinicios: maxIntentos
  }
};

// Se ejecuta despues del SSH de recuperacion.
const c = $('Control de reintentos').first().json;
const ssh = $json;   // { stdout, stderr, code } o { error } si no pudo conectarse
let error = '';
if (ssh.error) error = String(ssh.error.message || ssh.error);
else if (ssh.code !== 0 && ssh.code !== undefined) error = String(ssh.stderr || ssh.stdout || 'codigo ' + ssh.code);
return { json: { ...c, t_reinicio_ms: Date.now(), reinicio_ok: error === '', reinicio_error: error.slice(0, 300) } };

const r = $('Marcar hora de la accion').first().json;
const ssh = $json;

// Primera línea devuelta por la verificación SSH
const l0 = String(ssh.stdout || '')
  .trim()
  .split(/\r?\n/)[0]
  .trim();


// ==================================================
// VERIFICACION REAL
// ==================================================

const verifOk =
  r.esperado === 'num'
    ? Number(l0) >= 1
    : l0.toLowerCase() === String(r.esperado).toLowerCase();

const ok = !ssh.error && verifOk;


// ==================================================
// TEXTO DE VERIFICACION
// ==================================================

const verificacion = ok
  ? `Verificación correcta: ${l0 || 'servicio activo'}`
  : (
      ssh.error
        ? `Error SSH durante la verificación: ${ssh.error}`
        : `Verificación incorrecta. Obtenido: ${l0 || 'vacío'}`
    );


// ==================================================
// TIEMPOS
// ==================================================

const ahora = Date.now();

const ref =
  r.t_evento_ms != null
    ? r.t_evento_ms
    : r.t_inicio_ms;


const seg = (a, b) =>
  (a == null || b == null)
    ? null
    : Math.round((b - a) / 100) / 10;


const f = v =>
  v == null
    ? 'n/d'
    : v + ' s';


const hora = ms =>
  ms == null
    ? 'n/d'
    : new Date(ms - 6 * 3600 * 1000)
        .toISOString()
        .replace('T', ' ')
        .slice(0, 19) + ' (CR)';


const tAccion =
  seg(
    ref,
    r.t_reinicio_ms
  );


const tTotal =
  seg(
    ref,
    ahora
  );


// ==================================================
// MENSAJE
// ==================================================

const lin = [

  (ok ? '✅ RECUPERADO: ' : '❌ FALLO: ') +
    r.etiqueta +
    ' | ' +
    r.categoria,

  'Trigger: ' +
    r.trigger,

  'Hora del evento: ' +
    (
      r.event_time
        ? r.event_time + ' (Zabbix)'
        : hora(r.t_inicio_ms) + ' (llegada a n8n)'
    ),

  (ok
    ? 'Hora de recuperacion: '
    : 'Hora del fallo: '
  ) +
    hora(ahora),

  'Diagnostico: ' +
    (r.diag || 'n/d'),

  'Decision: ' +
    (r.razon || 'n/d'),

  'Accion: ' +
    (
      r.reinicio_ok
        ? 'ejecutada'
        : 'con error: ' +
          (r.reinicio_error || 'desconocido')
    ),

  'Verificacion: ' +
    verificacion,

  'T-accion: ' +
    f(tAccion) +
    ' | T-total: ' +
    f(tTotal),

  ok
    ? 'Nota: la alerta de Zabbix se cierra sola cuando el problema desaparece.'
    : 'La recuperación automática no fue confirmada.',

  'Intentos: ' +
    (r.intentos_en_ventana ?? r.intento ?? 'n/d') +
    ' de ' +
    (r.max_reinicios ?? r.max ?? 4)

];


// ==================================================
// SALIDA
// ==================================================

return {
  json: {

    ...r,

    ok,

    estado:
      ok
        ? 'RECUPERADO'
        : 'FALLO',

    verificacion,

    tiempos: {
      accion: tAccion,
      total: tTotal
    },

    mensaje:
      lin.join('\n')

  }
};
